<nav class="book-toc" aria-label="Book table of contents"><ol><?php foreach($chapters as $chapter):?><li<?=empty($chapter['available'])?' class="is-unavailable"':''?>><span class="book-toc__number"><?=Security::e($chapter['number'])?></span><span><?php if(!empty($chapter['available'])):?><a href="<?=Security::e($chapter['href'])?>"><?=Security::e($chapter['label'])?></a><?php else:?><span aria-disabled="true"><?=Security::e($chapter['label'])?></span><?php endif;?><small><?=Security::e($chapter['title'])?></small></span></li><?php endforeach;?></ol></nav>
